#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"
source "$HOME/.companyos_launch_env" 2>/dev/null || true
STAMP="$(date +%Y%m%d_%H%M%S)"
BK="$HOME/companyos/.companyos_backups/research_execution_v3_$STAMP"
mkdir -p "$BK"
cp companyos/runtime/profit_opportunity_runtime.py "$BK/" 2>/dev/null || true
cp companyos/runtime/profit_first_dispatcher.py "$BK/" 2>/dev/null || true

echo "" | base64 -d > companyos/runtime/candidate_enrichment_bridge.py
echo "" | base64 -d > companyos/runtime/profit_opportunity_runtime.py
echo "" | base64 -d > "$PREFIX/tmp/companyos_goal_append.py"

python - "$PREFIX/tmp/companyos_goal_append.py" <<'PY'
from pathlib import Path
import sys
target=Path("companyos/runtime/profit_first_dispatcher.py")
append=Path(sys.argv[1]).read_text()
s=target.read_text()
if "# COMPANYOS_TARGETED_ENRICHMENT_CONTRACT_V3" not in s:
    target.write_text(s+"\n"+append+"\n")
    print("TARGETED_ENRICHMENT_DISPATCHER=INSTALLED")
else:
    print("TARGETED_ENRICHMENT_DISPATCHER=ALREADY_INSTALLED")
PY
rm -f "$PREFIX/tmp/companyos_goal_append.py"

python -m py_compile companyos/runtime/candidate_enrichment_bridge.py companyos/runtime/profit_opportunity_runtime.py companyos/runtime/profit_first_dispatcher.py
python -m companyos.runtime.candidate_enrichment_bridge

python - <<'PY'
from companyos.runtime.profit_first_dispatcher import build_goal
g=build_goal()
assert "TARGETED ENRICHMENT CONTRACT" in g
print("TARGETED_ENRICHMENT_GOAL=PASS")
PY

git add companyos/runtime/candidate_enrichment_bridge.py companyos/runtime/profit_opportunity_runtime.py companyos/runtime/profit_first_dispatcher.py
git diff --cached --quiet || git commit -m "Convert targeted research into execution-qualified candidates"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true

scripts/companyosctl restart || true
sleep 8

python - <<'PY'
import json
from companyos.runtime.profit_first_dispatcher import maybe_dispatch
print(json.dumps(maybe_dispatch(min_idle_cycles=0,cooldown_seconds=0),indent=2,sort_keys=True,default=str))
PY

echo "===== BRIDGE STATE ====="
cat .companyos_runtime/candidate_enrichment_bridge_state.json 2>/dev/null || true
echo "===== PROFIT STATUS ====="
python - <<'PY'
from companyos.runtime.profit_opportunity_engine import choose
x=choose()
print("candidate_count =",x.get("candidate_count"))
print("eligible_count =",x.get("eligible_count"))
print("decision =",x.get("decision"))
print("chosen =", (x.get("chosen") or {}).get("name"))
print("enrichment_queue_count =",x.get("enrichment_queue_count"))
PY
echo "===== SERVICES ====="
scripts/companyosctl status || true
echo "COMPANYOS_RESEARCH_EXECUTION_CONVERSION_FIX_V3_1=PASS"
